import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class TextNodeTest {

    @Mock
    private LeafNode leafNodeMock;

    public TextNode textNode(String text) {
        return new TextNode(text);
    }

    @Test
    public void nodeNameIsText() {
        String nodeName = textNode("test").nodeName();
        assertEquals("text", nodeName);
    }

    @Test
    public void textReturnsOriginalText() {
        String originalText = "test";
        when(leafNodeMock.text()).thenReturn(originalText);
        String result = textNode(originalText).text();
        assertEquals(originalText, result);
    }

    @Test
    public void textChangesText() {
        String originalText = "test";
        String newText = "newText";
        when(leafNodeMock.text()).thenReturn(originalText);
        TextNode textNode = new TextNode(originalText);
        textNode.text(newText);
        assertEquals(newText, textNode.text());
    }

    @Test
    public void getWholeTextReturnsOriginalText() {
        String originalText = "test";
        when(leafNodeMock.text()).thenReturn(originalText);
        String result = textNode(originalText).getWholeText();
        assertEquals(originalText, result);
    }

    @Test
    public void isBlankReturnsFalseIfNotBlank() {
        assertFalse(textNode("test").isBlank());
    }

    @Test
    public void isBlankReturnsTrueIfBlank() {
        assertTrue(textNode("").isBlank());
    }

    @Test
    public void splitTextUpdatesText() {
        String originalText = "test";
        when(leafNodeMock.text()).thenReturn(originalText);
        TextNode textNode = new TextNode(originalText);
        int offset = 5;
        String result = textNode.splitText(offset).text();
        assertEquals(originalText.substring(0, offset), result);
    }

    @Test
    public void cloneReturnsClone() {
        TextNode textNode = textNode("test");
        when(leafNodeMock.text()).thenReturn(textNode.text());
        TextNode cloned = textNode.clone();
        assertEquals(cloned, cloned.clone());
    }

    @Test
    public void createFromEncodedCreatesTextNodes() {
        String encodedText = "test";
        when(StringUtil normaliseWhitespace(encodedText)).thenReturn("test");
        when(leafNodeMock.text()).thenReturn("test");
        TextNode textNode = TextNode.createFromEncoded(encodedText);
        assertEquals(textNode, new TextNode(textNode.text()));
    }

    @Test
    public void normaliseWhitespaceReturnsOriginalString() {
        String originalText = "test ";
        when(StringUtil.stripLeadingWhitespace(originalText)).thenReturn(originalText);
        assertEquals(originalText, StringUtil.normaliseWhitespace(originalText));
    }

    @Test
    public void stripLeadingWhitespaceReturnsEmptyIfBlank() {
        String originalText = "";
        when(StringUtil.stripLeadingWhitespace(originalText)).thenReturn("");
        assertEquals("", StringUtil.stripLeadingWhitespace(originalText));
    }

    @Test
    public void lastCharIsWhitespaceReturnsFalseForNonWhitespaces() {
        assertFalse(lastCharIsWhitespace("test"));
    }

    @Test
    public void lastCharIsWhitespaceReturnsTrueIfEndsWithWhitespace() {
        assertTrue(lastCharIsWhitespace(" test "));
    }
}
